syntax = "proto3";

service UserService {

  rpc GetUser (GetUserRequest) returns (User);
  rpc StreamUsers (StreamRequest) returns (stream User);
}

message GetUserRequest {

  int64 user_id = 1;
}

message User {

  int64  user_id   = 1;
  string name      = 2;
  string email     = 3;
  int32  age       = 4;
  bool   is_active = 5;

}

